) v(unit_id,candidate_id,d,code,ed,desig,rel) LOOP
  BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.attendance_entries e WHERE e.unit_id=r.unit_id::uuid AND e.candidate_id=r.candidate_id::uuid AND e.entry_date=r.d::date) THEN
      INSERT INTO public.attendance_entries(unit_id,candidate_id,entry_date,code,ot_hours,designation_id,shift_hours,is_reliever)
